const model = (name, ownership = "external-authoritative") => ({
    name,
    authority: "external",
    ownership,
    fields: [
        {
            name: "id",
            type: "text",
            immutable: true,
            externally_owned: true,
            application_readable: true,
        },
        {
            name: "status",
            type: "text",
            optional: true,
            externally_owned: true,
            application_readable: true,
        },
        {
            name: "created_at",
            type: "datetime",
            externally_owned: true,
            application_readable: true,
        },
        {
            name: "metadata",
            type: "json",
            optional: true,
            externally_owned: true,
            application_readable: true,
        },
    ],
});
